// src/components/PracticeDashboard.tsx

import { useState, useEffect, useMemo } from 'react';
import type React from 'react';
import { useMusic } from '../context/MusicContext';
import { playChordByName, playScale } from '../utils/audioEngine';
import {
  PRACTICE_PLANS,
  getNextExercise,
  getUserProgress,
  updateProgress,
  type Exercise,
  type UserProgress,
  type PracticePlan
} from '../data/practice_module';
import { Button } from './ui/Button';
import { IconButton } from './ui/IconButton';
import { Spinner } from './ui/Spinner';
import ChordDictionaryModal from './tools/ChordDictionaryModal';

const CATEGORY_LABELS: Record<Exercise['category'], string> = {
  chords: 'Chords',
  scales: 'Scales',
  rhythm: 'Rhythm',
  technique: 'Technique',
  improvisation: 'Improv',
  ear_training: 'Ear',
};

const CATEGORY_ICONS: Record<Exercise['category'], string> = {
  chords: '🎸',
  scales: '🎵',
  rhythm: '🥁',
  technique: '🔥',
  improvisation: '✨',
  ear_training: '👂',
};

const DIFFICULTY_LABELS: Record<Exercise['difficulty'], string> = {
  beginner: 'Beginner',
  intermediate: 'Intermediate',
  advanced: 'Advanced',
  pro: 'Pro',
};

function formatLastPractice(isoDate: string): string {
  if (!isoDate) return '—';
  const today = new Date().toISOString().split('T')[0];
  if (isoDate === today) return 'сегодня';
  const yesterday = new Date();
  yesterday.setDate(yesterday.getDate() - 1);
  const yIso = yesterday.toISOString().split('T')[0];
  if (isoDate === yIso) return 'вчера';
  const days = Math.floor((Date.now() - new Date(isoDate).getTime()) / 86_400_000);
  if (days < 7) return `${days} дн. назад`;
  return new Date(isoDate).toLocaleDateString('ru-RU', { day: 'numeric', month: 'short' });
}

const PracticeDashboard: React.FC = () => {
  const { getScaleNotes, bpm } = useMusic();
  const [userProgress, setUserProgress] = useState<UserProgress>(() => {
    const saved = localStorage.getItem('fretlab_practice_progress');
    return saved ? JSON.parse(saved) : getUserProgress();
  });
  const [currentPlan, setCurrentPlan] = useState<PracticePlan>(PRACTICE_PLANS[0]);
  const [categoryFilter, setCategoryFilter] = useState<Exercise['category'] | 'all'>('all');
  const [selectedExercise, setSelectedExercise] = useState<Exercise | null>(null);
  const [isPracticing, setIsPracticing] = useState(false);
  const [isPlayingAudio, setIsPlayingAudio] = useState<string | null>(null); // 'chord' | 'tab' | null
  const [selectedChord, setSelectedChord] = useState<string | null>(null);
  const [showChordModal, setShowChordModal] = useState(false);
  const [showResetConfirm, setShowResetConfirm] = useState(false);
  const [sessionStart, setSessionStart] = useState<number | null>(null);
  const [elapsed, setElapsed] = useState(0);

  useEffect(() => {
    localStorage.setItem('fretlab_practice_progress', JSON.stringify(userProgress));
  }, [userProgress]);

  // Practice session timer
  useEffect(() => {
    if (sessionStart === null) return;
    const id = setInterval(() => setElapsed(Math.floor((Date.now() - sessionStart) / 1000)), 1000);
    return () => clearInterval(id);
  }, [sessionStart]);

  const handleStartExercise = (exercise: Exercise) => {
    setSelectedExercise(exercise);
    setIsPracticing(true);
    setSessionStart(Date.now());
    setElapsed(0);
  };

  const handleCloseModal = () => {
    setSelectedExercise(null);
    setIsPracticing(false);
    setSessionStart(null);
    setElapsed(0);
    setIsPlayingAudio(null);
  };

  const handleCompleteExercise = () => {
    if (!selectedExercise) return;
    const updated = updateProgress(userProgress, selectedExercise.id);
    setUserProgress(updated);
    handleCloseModal();
  };

  const handleResetProgress = () => {
    localStorage.removeItem('fretlab_practice_progress');
    setUserProgress(getUserProgress());
    setShowResetConfirm(false);
  };

  const playChordAudio = (chordName: string) => {
    if (isPlayingAudio) return;
    setIsPlayingAudio('chord');
    playChordByName(chordName);
    setTimeout(() => setIsPlayingAudio(null), 2500);
  };

  // 🔥 ВОСПРОИЗВЕДЕНИЕ ТАБА
  const playTabAudio = (tabData: any) => {
    if (isPlayingAudio || !tabData) return;
    setIsPlayingAudio('tab');

    try {
      const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
      const ctx = new AudioContextClass();
      const OPEN_FREQS = [329.63, 246.94, 196.00, 146.83, 110.00, 82.41];

      let startTime = ctx.currentTime + 0.1;
      const quarterDuration = 60 / (bpm || 120);

      tabData.notes.forEach((note: any) => {
        const fretValue = note.fret ?? 0;
        const freq = OPEN_FREQS[note.string] * Math.pow(2, fretValue / 12);

        const durationMap: Record<string, number> = {
          'whole': 4, 'half': 2, 'quarter': 1, 'eighth': 0.5,
          'sixteenth': 0.25, 'dotted_eighth': 0.75,
        };
        const noteDuration = quarterDuration * (durationMap[note.duration] || 0.5);
        const actualDuration = noteDuration * 0.9;

        const osc = ctx.createOscillator();
        const gainNode = ctx.createGain();

        osc.type = note.technique === 'bend' ? 'sawtooth' : 'triangle';
        osc.frequency.setValueAtTime(freq, startTime);

        gainNode.gain.setValueAtTime(0, startTime);
        gainNode.gain.linearRampToValueAtTime(0.4, startTime + 0.02);
        gainNode.gain.exponentialRampToValueAtTime(0.001, startTime + actualDuration);

        osc.connect(gainNode);
        gainNode.connect(ctx.destination);
        osc.start(startTime);
        osc.stop(startTime + actualDuration + 0.1);

        startTime += actualDuration;
      });

      setTimeout(() => setIsPlayingAudio(null), (startTime - ctx.currentTime) * 1000 + 500);
    } catch (e) {
      console.error("Audio Synthesis Failed:", e);
      setIsPlayingAudio(null);
    }
  };

  // 🔥 ВОСПРОИЗВЕДЕНИЕ ПРИМЕРА ИЗ УРОКА
  const playExerciseAudio = (exercise: Exercise) => {
    if (isPlayingAudio) return;

    if (exercise.tabData) {
      playTabAudio(exercise.tabData);
      return;
    }

    if (exercise.chords && exercise.chords.length > 0) {
      setIsPlayingAudio('chord');
      exercise.chords.forEach((chord, index) => {
        setTimeout(() => playChordByName(chord), index * 2000);
      });
      setTimeout(() => setIsPlayingAudio(null), exercise.chords.length * 2000 + 500);
      return;
    }

    if (exercise.category === 'scales') {
      const scale = getScaleNotes();
      if (scale.length > 0) {
        const notes = scale.map(n => n + '4');
        playScale(notes, 150);
      }
      setIsPlayingAudio('chord');
      setTimeout(() => setIsPlayingAudio(null), 3000);
      return;
    }

    const scale = getScaleNotes();
    if (scale.length > 0) {
      playChordByName(scale[0] + 'maj');
    }
    setIsPlayingAudio('chord');
    setTimeout(() => setIsPlayingAudio(null), 2500);
  };

  const getSkillColor = (value: number) => {
    if (value >= 80) return 'var(--accent)';
    if (value >= 50) return '#ffb800';
    return 'var(--text-muted)';
  };

  // Filtering
  const filteredExercises = useMemo(() => {
    if (categoryFilter === 'all') return currentPlan.exercises;
    return currentPlan.exercises.filter(e => e.category === categoryFilter);
  }, [currentPlan, categoryFilter]);

  const nextExercise = getNextExercise(userProgress, currentPlan);
  const allCategories: (Exercise['category'] | 'all')[] = ['all', 'chords', 'scales', 'rhythm', 'technique', 'improvisation', 'ear_training'];

  const planProgress = currentPlan.exercises.length > 0
    ? Math.round((userProgress.completedExercises.length / currentPlan.exercises.length) * 100)
    : 0;

  // Session timer formatter
  const formatSession = (s: number) => {
    const m = Math.floor(s / 60);
    const sec = s % 60;
    return `${m}:${sec.toString().padStart(2, '0')}`;
  };

  // ============================================================
  // 🎸 РЕНДЕР АККОРДОВ
  // ============================================================
  const renderChords = (exercise: Exercise) => {
    if (!exercise.chords || exercise.chords.length === 0) return null;

    return (
      <div className="fl-section-panel fl-section-panel--muted">
        <span className="fl-section-label">🎸 Аккорды в уроке</span>
        <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap', flex: 1 }}>
          {exercise.chords.map((chord) => (
            <Button
              key={chord}
              variant="secondary"
              size="sm"
              onClick={() => {
                setSelectedChord(chord);
                setShowChordModal(true);
                playChordAudio(chord);
              }}
              aria-label={`Посмотреть аппликатуру ${chord}`}
            >
              🎵 {chord}
            </Button>
          ))}
        </div>
        <Button
          variant="primary"
          size="sm"
          onClick={() => playExerciseAudio(exercise)}
          disabled={isPlayingAudio !== null}
          loading={isPlayingAudio === 'chord'}
          iconLeft="▶"
        >
          Play All
        </Button>
      </div>
    );
  };

  // ============================================================
  // 🎼 РЕНДЕР ТАБОВ
  // ============================================================
  const renderTab = (exercise: Exercise) => {
    if (!exercise.tabData) return null;

    const tabNotes = exercise.tabData.notes || [];
    const stringSpacing = 20;
    const startY = 30;
    const noteSpacing = 60;
    const startX = 40;

    return (
      <div className="fl-section-panel fl-section-panel--muted" style={{ flexDirection: 'column', alignItems: 'stretch' }}>
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', width: '100%' }}>
          <span className="fl-section-label">🎼 Табулатура</span>
          <Button
            variant="primary"
            size="sm"
            onClick={() => playExerciseAudio(exercise)}
            disabled={isPlayingAudio !== null}
            loading={isPlayingAudio === 'tab'}
            iconLeft="▶"
          >
            Play Tab
          </Button>
        </div>

        <div style={{ overflowX: 'auto', width: '100%' }}>
          <svg
            viewBox={`0 0 ${Math.max(400, tabNotes.length * noteSpacing + 100)} 160`}
            style={{ width: '100%', minWidth: '350px', height: '140px', display: 'block' }}
            role="img"
            aria-label={`Табулатура для ${exercise.title}`}
          >
            {/* Струны */}
            {[0, 1, 2, 3, 4, 5].map((strIndex) => (
              <line
                key={`str-${strIndex}`}
                x1="30" y1={startY + strIndex * stringSpacing}
                x2={Math.max(380, tabNotes.length * noteSpacing + 60)} y2={startY + strIndex * stringSpacing}
                stroke="var(--color-surface-3)" strokeWidth="1.5"
              />
            ))}

            {/* Названия струн */}
            {['e', 'B', 'G', 'D', 'A', 'E'].map((note, i) => (
              <text
                key={`tune-${i}`}
                x="15" y={startY + i * stringSpacing + 4}
                fill="var(--text-muted)"
                fontSize="10"
                fontWeight="800"
                fontFamily="var(--font-mono)"
                textAnchor="middle"
              >
                {note}
              </text>
            ))}

            {/* Ноты */}
            {tabNotes.map((note, index) => {
              const x = startX + index * noteSpacing;
              const y = startY + note.string * stringSpacing;
              const isTechnique = note.technique === 'bend' || note.technique === 'vibrato';
              return (
                <g key={`note-${index}`}>
                  <rect x={x - 10} y={y - 10} width="20" height="20" fill="var(--bg-secondary)" rx="3" />
                  <text
                    x={x} y={y + 4}
                    fill={isTechnique ? 'var(--accent)' : 'var(--text-primary)'}
                    fontSize="13"
                    fontWeight={note.technique === 'bend' ? 900 : 700}
                    fontFamily="var(--font-mono)"
                    textAnchor="middle"
                  >
                    {note.fret}
                  </text>
                  {note.technique === 'hammer' && (
                    <text x={x} y={y - 16} fill="var(--accent)" fontSize="9" fontWeight="800" textAnchor="middle">H</text>
                  )}
                  {note.technique === 'pull' && (
                    <text x={x} y={y - 16} fill="var(--accent)" fontSize="9" fontWeight="800" textAnchor="middle">P</text>
                  )}
                  {note.technique === 'slide' && (
                    <text x={x} y={y - 16} fill="var(--accent)" fontSize="9" fontWeight="800" textAnchor="middle">sl</text>
                  )}
                  {note.technique === 'bend' && (
                    <text x={x} y={y - 16} fill="var(--accent)" fontSize="9" fontWeight="800" textAnchor="middle">b</text>
                  )}
                </g>
              );
            })}
          </svg>
        </div>
      </div>
    );
  };

  // ============================================================
  // 📋 РЕНДЕР КОНТЕНТА УРОКА
  // ============================================================
  const renderExerciseContent = (exercise: Exercise) => {
    return (
      <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>

        {/* Описание */}
        <div className="fl-section-panel fl-section-panel--muted" style={{ flexDirection: 'column', alignItems: 'stretch' }}>
          <span className="fl-section-label">📝 Описание</span>
          <div style={{ fontSize: 'var(--text-base)', color: 'var(--text-secondary)', lineHeight: 'var(--leading-relaxed)' }}>
            {exercise.description}
          </div>
        </div>

        {/* 🎯 Цель */}
        <div className="fl-section-panel">
          <span className="fl-section-label" style={{ color: 'var(--accent)' }}>🎯 Цель</span>
          <div style={{ fontSize: 'var(--text-base)', color: 'var(--text-primary)', fontWeight: 600, flex: 1 }}>
            {exercise.goal}
          </div>
        </div>

        {/* 📖 Теория */}
        {exercise.theory && (
          <div className="fl-section-panel fl-section-panel--muted" style={{ flexDirection: 'column', alignItems: 'stretch' }}>
            <span className="fl-section-label">📖 Теория</span>
            <div style={{ fontSize: 'var(--text-base)', color: 'var(--text-secondary)', lineHeight: 'var(--leading-relaxed)', whiteSpace: 'pre-wrap' }}>
              {exercise.theory}
            </div>
          </div>
        )}

        {/* 🖐️ Постановка пальцев */}
        {exercise.fingerPosition && (
          <div className="fl-section-panel fl-section-panel--muted" style={{ flexDirection: 'column', alignItems: 'stretch' }}>
            <span className="fl-section-label">🖐️ Постановка пальцев</span>
            <div style={{ fontSize: 'var(--text-base)', color: 'var(--text-secondary)', lineHeight: 'var(--leading-relaxed)', whiteSpace: 'pre-wrap' }}>
              {exercise.fingerPosition}
            </div>
          </div>
        )}

        {/* 💡 Советы */}
        {exercise.tips && exercise.tips.length > 0 && (
          <div
            className="fl-section-panel fl-section-panel--muted"
            style={{
              flexDirection: 'column',
              alignItems: 'stretch',
              background: 'rgba(255, 184, 0, 0.06)',
              borderColor: 'rgba(255, 184, 0, 0.2)',
            }}
          >
            <span className="fl-section-label" style={{ color: '#ffb800' }}>💡 Советы</span>
            <ul style={{ margin: 0, paddingLeft: '20px', color: 'var(--text-secondary)', fontSize: 'var(--text-base)', lineHeight: 'var(--leading-relaxed)' }}>
              {exercise.tips.map((tip, idx) => (
                <li key={idx}>{tip}</li>
              ))}
            </ul>
          </div>
        )}

        {/* 📋 Практические шаги */}
        {exercise.practiceSteps && exercise.practiceSteps.length > 0 && (
          <div className="fl-section-panel fl-section-panel--muted" style={{ flexDirection: 'column', alignItems: 'stretch' }}>
            <span className="fl-section-label">📋 Шаги</span>
            <ol style={{ margin: 0, paddingLeft: '20px', color: 'var(--text-secondary)', fontSize: 'var(--text-base)', lineHeight: 'var(--leading-relaxed)' }}>
              {exercise.practiceSteps.map((step, idx) => (
                <li key={idx}>{step}</li>
              ))}
            </ol>
          </div>
        )}

        {/* 🔥 АККОРДЫ или ТАБЫ */}
        {exercise.displayType === 'chords' && renderChords(exercise)}
        {exercise.displayType === 'tab' && renderTab(exercise)}
        {!exercise.displayType && exercise.chords && exercise.chords.length > 0 && renderChords(exercise)}
        {!exercise.displayType && exercise.tabData && renderTab(exercise)}
      </div>
    );
  };

  // ============================================================
  // 🎨 STAT CARD (helper for status bar)
  // ============================================================
  const StatCard: React.FC<{ label: string; value: string; accent?: boolean; hint?: string }> = ({ label, value, accent, hint }) => (
    <div>
      <div className="fl-section-label" style={{ marginBottom: 6 }}>{label}</div>
      <div style={{
        fontSize: 'var(--text-2xl)',
        fontWeight: 900,
        color: accent ? 'var(--accent)' : 'var(--text-primary)',
        fontFamily: 'var(--font-mono)',
        lineHeight: 1,
      }}>
        {value}
      </div>
      {hint && (
        <div style={{ fontSize: 'var(--text-xs)', color: 'var(--text-muted)', marginTop: 4 }}>{hint}</div>
      )}
    </div>
  );

  return (
    <div style={{
      background: 'var(--bg-root)',
      minHeight: '100%',
      padding: '32px 40px',
      display: 'flex',
      flexDirection: 'column',
      gap: '24px',
    }}>

      {/* ===== ЗАГОЛОВОК ===== */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', flexWrap: 'wrap', gap: 12 }}>
        <div>
          <h1 style={{ margin: 0, fontSize: 'var(--text-2xl)', fontWeight: 900, color: 'var(--text-primary)' }}>
            🏋️ Practice Module
          </h1>
          <p style={{ margin: '4px 0 0 0', color: 'var(--text-muted)', fontSize: 'var(--text-sm)' }}>
            Твоя персональная система тренировок
          </p>
        </div>
        <div style={{ display: 'flex', gap: '8px', alignItems: 'center', flexWrap: 'wrap' }}>
          <span
            aria-label={`Серия ${userProgress.practiceStreak} ${userProgress.practiceStreak === 1 ? 'день' : 'дней'}`}
            style={{
              display: 'inline-flex',
              alignItems: 'center',
              gap: 6,
              background: 'var(--bg-panel)',
              padding: '6px 14px',
              borderRadius: 'var(--radius-full)',
              fontSize: 'var(--text-sm)',
              fontWeight: 700,
              color: userProgress.practiceStreak > 0 ? 'var(--accent)' : 'var(--text-muted)',
              border: '1px solid var(--border-color)',
              fontFamily: 'var(--font-mono)',
            }}
          >
            <span
              aria-hidden="true"
              style={{
                display: 'inline-block',
                width: 8,
                height: 8,
                borderRadius: '50%',
                background: userProgress.practiceStreak > 0 ? 'var(--accent)' : 'var(--text-muted)',
                boxShadow: userProgress.practiceStreak > 0 ? '0 0 8px var(--color-accent-glow)' : 'none',
                animation: userProgress.practiceStreak > 0 ? 'fretlab-pulse 2s ease-in-out infinite' : 'none',
              }}
            />
            🔥 {userProgress.practiceStreak} {userProgress.practiceStreak === 1 ? 'день' : 'дн.'}
          </span>
          <span
            style={{
              background: 'var(--bg-panel)',
              padding: '6px 14px',
              borderRadius: 'var(--radius-full)',
              fontSize: 'var(--text-sm)',
              color: 'var(--accent)',
              border: '1px solid var(--accent)',
              fontWeight: 700,
              textTransform: 'capitalize',
            }}
          >
            {DIFFICULTY_LABELS[userProgress.currentLevel]}
          </span>
          <Button
            variant="ghost"
            size="sm"
            onClick={() => setShowResetConfirm(true)}
            aria-label="Сбросить прогресс"
            title="Сбросить весь прогресс"
          >
            ↺ Reset
          </Button>
        </div>
      </div>

      {/* ===== СТАТУС БАР ===== */}
      <div
        className="fl-section-panel fl-section-panel--muted"
        style={{ alignItems: 'flex-start' }}
      >
        <StatCard
          label="Выполнено"
          value={String(userProgress.completedExercises.length)}
          accent
        />
        <StatCard
          label="Прогресс плана"
          value={`${planProgress}%`}
        />
        <StatCard
          label="Текущий план"
          value={currentPlan.name.replace(/^[^A-Za-zА-Яа-я]+/, '')}
          hint={`${currentPlan.totalWeeks} ${currentPlan.totalWeeks === 1 ? 'неделя' : 'нед.'}`}
        />
        <StatCard
          label="Время"
          value={`${userProgress.completedExercises.length * 15} min`}
          hint={`Последний раз: ${formatLastPractice(userProgress.lastPracticeDate)}`}
        />
      </div>

      {/* ===== СЛЕДУЮЩЕЕ УПРАЖНЕНИЕ ===== */}
      {nextExercise ? (
        <div
          className="fl-section-panel"
          style={{
            borderColor: 'var(--color-accent-border)',
            boxShadow: '0 0 30px rgba(0, 255, 157, 0.06)',
          }}
        >
          <div style={{ flex: 1, minWidth: 0 }}>
            <div
              className="fl-section-label"
              style={{ color: 'var(--accent)', display: 'flex', alignItems: 'center', gap: 6 }}
            >
              <span
                aria-hidden="true"
                style={{
                  display: 'inline-block',
                  width: 6,
                  height: 6,
                  borderRadius: '50%',
                  background: 'var(--accent)',
                  boxShadow: '0 0 6px var(--accent)',
                  animation: 'fretlab-pulse 1.8s ease-in-out infinite',
                }}
              />
              Next Up
            </div>
            <h3 style={{ margin: '6px 0 4px 0', fontSize: 'var(--text-xl)', fontWeight: 800, color: 'var(--text-primary)' }}>
              {nextExercise.title}
            </h3>
            <p style={{ margin: 0, color: 'var(--text-muted)', fontSize: 'var(--text-sm)' }}>
              {nextExercise.description}
            </p>
            <div style={{ display: 'flex', gap: '6px', marginTop: '8px', flexWrap: 'wrap' }}>
              <span style={tagStyle('muted')}>⏱️ {nextExercise.estimatedTime}</span>
              <span style={tagStyle('accent')}>{DIFFICULTY_LABELS[nextExercise.difficulty]}</span>
              <span style={tagStyle('muted')}>{CATEGORY_ICONS[nextExercise.category]} {CATEGORY_LABELS[nextExercise.category]}</span>
            </div>
          </div>
          <Button
            variant="primary"
            size="lg"
            onClick={() => handleStartExercise(nextExercise)}
            iconLeft="▶"
            aria-label={`Начать упражнение: ${nextExercise.title}`}
          >
            Start Practice
          </Button>
        </div>
      ) : (
        <div
          className="fl-section-panel"
          style={{
            flexDirection: 'column',
            alignItems: 'center',
            textAlign: 'center',
            padding: '24px',
            gap: 12,
          }}
        >
          <div style={{ fontSize: 48 }} aria-hidden="true">🎉</div>
          <div style={{ fontSize: 'var(--text-xl)', fontWeight: 800, color: 'var(--text-primary)' }}>
            Все уроки в плане выполнены!
          </div>
          <div style={{ fontSize: 'var(--text-sm)', color: 'var(--text-muted)' }}>
            Перейди на следующий уровень или сбрось прогресс, чтобы пройти заново.
          </div>
          <div style={{ display: 'flex', gap: 8, marginTop: 4 }}>
            {PRACTICE_PLANS.filter(p => p.level !== currentPlan.level).map(p => (
              <Button
                key={p.id}
                variant="secondary"
                size="sm"
                onClick={() => setCurrentPlan(p)}
              >
                {p.name}
              </Button>
            ))}
            <Button
              variant="ghost"
              size="sm"
              onClick={() => setShowResetConfirm(true)}
            >
              ↺ Reset
            </Button>
          </div>
        </div>
      )}

      {/* ===== ФИЛЬТРЫ ===== */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: 12 }}>
        <h2 style={{ margin: 0, fontSize: 'var(--text-lg)', fontWeight: 800, color: 'var(--text-primary)' }}>
          📋 Упражнения
        </h2>
        <div style={{ display: 'flex', gap: '6px', flexWrap: 'wrap' }}>
          {PRACTICE_PLANS.map((plan) => (
            <Button
              key={plan.id}
              variant="secondary"
              size="sm"
              active={currentPlan.id === plan.id}
              onClick={() => setCurrentPlan(plan)}
              aria-pressed={currentPlan.id === plan.id}
            >
              {plan.name}
            </Button>
          ))}
        </div>
      </div>

      <div style={{ display: 'flex', gap: '6px', flexWrap: 'wrap' }}>
        {allCategories.map((cat) => (
          <Button
            key={cat}
            variant="ghost"
            size="sm"
            active={categoryFilter === cat}
            onClick={() => setCategoryFilter(cat)}
            aria-pressed={categoryFilter === cat}
            iconLeft={cat === 'all' ? '·' : CATEGORY_ICONS[cat]}
          >
            {cat === 'all' ? 'Все' : CATEGORY_LABELS[cat]}
          </Button>
        ))}
      </div>

      {/* ===== СЕТКА УПРАЖНЕНИЙ ===== */}
      {filteredExercises.length === 0 ? (
        <div
          className="fl-section-panel fl-section-panel--muted"
          style={{ flexDirection: 'column', alignItems: 'center', textAlign: 'center', padding: '32px' }}
        >
          <div style={{ fontSize: 32 }} aria-hidden="true">🤷</div>
          <div style={{ color: 'var(--text-muted)', fontSize: 'var(--text-sm)', marginTop: 8 }}>
            Нет упражнений в этой категории
          </div>
        </div>
      ) : (
        <div
          style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))', gap: '12px' }}
          role="list"
        >
          {filteredExercises.map((exercise) => {
            const isCompleted = userProgress.completedExercises.includes(exercise.id);
            const isLocked = exercise.prerequisites?.some(p => !userProgress.completedExercises.includes(p));
            return (
              <button
                key={exercise.id}
                type="button"
                role="listitem"
                onClick={() => !isLocked && handleStartExercise(exercise)}
                disabled={isLocked}
                aria-label={`${isCompleted ? 'Завершено: ' : ''}${exercise.title}, ${DIFFICULTY_LABELS[exercise.difficulty]}, ${exercise.estimatedTime}${isLocked ? ' (заблокировано)' : ''}`}
                style={{
                  textAlign: 'left',
                  background: isCompleted ? 'var(--bg-primary)' : 'var(--bg-panel)',
                  border: `1px solid ${isCompleted ? 'var(--color-accent-border)' : 'var(--border-color)'}`,
                  borderRadius: 'var(--radius-lg)',
                  padding: '14px 16px',
                  cursor: isLocked ? 'not-allowed' : 'pointer',
                  opacity: isLocked ? 0.5 : isCompleted ? 0.8 : 1,
                  fontFamily: 'inherit',
                  color: 'inherit',
                  display: 'flex',
                  flexDirection: 'column',
                  gap: 8,
                  transition: 'all var(--transition-base)',
                  position: 'relative',
                }}
                onMouseEnter={(e) => {
                  if (!isLocked && !isCompleted) {
                    e.currentTarget.style.borderColor = 'var(--accent)';
                    e.currentTarget.style.transform = 'translateY(-2px)';
                  }
                }}
                onMouseLeave={(e) => {
                  if (!isLocked && !isCompleted) {
                    e.currentTarget.style.borderColor = 'var(--border-color)';
                    e.currentTarget.style.transform = 'translateY(0)';
                  }
                }}
              >
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', gap: 8 }}>
                  <div style={{ fontSize: 'var(--text-base)', fontWeight: 800, color: 'var(--text-primary)' }}>
                    {exercise.title}
                  </div>
                  {isCompleted ? (
                    <span
                      aria-hidden="true"
                      style={{
                        width: 22, height: 22, borderRadius: '50%',
                        background: 'var(--accent)', color: '#000',
                        display: 'inline-flex', alignItems: 'center', justifyContent: 'center',
                        fontSize: 13, fontWeight: 900, flexShrink: 0,
                      }}
                    >
                      ✓
                    </span>
                  ) : isLocked ? (
                    <span aria-label="Заблокировано" style={{ fontSize: 16 }}>🔒</span>
                  ) : null}
                </div>
                <div style={{ fontSize: 'var(--text-sm)', color: 'var(--text-muted)', lineHeight: 'var(--leading-normal)' }}>
                  {exercise.description}
                </div>
                <div style={{ display: 'flex', gap: '6px', flexWrap: 'wrap' }}>
                  <span style={tagStyle('muted')}>⏱️ {exercise.estimatedTime}</span>
                  <span style={tagStyle(isCompleted ? 'accent' : 'muted')}>{DIFFICULTY_LABELS[exercise.difficulty]}</span>
                  <span style={tagStyle('muted')}>{CATEGORY_ICONS[exercise.category]} {CATEGORY_LABELS[exercise.category]}</span>
                </div>
              </button>
            );
          })}
        </div>
      )}

      {/* ===== НАВЫКИ ===== */}
      <div className="fl-section-panel fl-section-panel--muted" style={{ flexDirection: 'column', alignItems: 'stretch' }}>
        <span className="fl-section-label">📊 Навыки</span>
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(180px, 1fr))', gap: '14px', width: '100%' }}>
          {(Object.keys(CATEGORY_LABELS) as Array<keyof UserProgress['skillLevels']>).map((skill) => {
            const value = userProgress.skillLevels[skill] || 0;
            return (
              <div key={skill}>
                <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: 'var(--text-sm)', marginBottom: 4 }}>
                  <span style={{ color: 'var(--text-secondary)' }}>
                    {CATEGORY_ICONS[skill]} {CATEGORY_LABELS[skill]}
                  </span>
                  <span style={{ color: getSkillColor(value), fontWeight: 800, fontFamily: 'var(--font-mono)' }}>
                    {value}%
                  </span>
                </div>
                <div
                  role="progressbar"
                  aria-valuenow={value}
                  aria-valuemin={0}
                  aria-valuemax={100}
                  aria-label={`Уровень навыка ${CATEGORY_LABELS[skill]}`}
                  style={{
                    height: '6px',
                    background: 'var(--bg-secondary)',
                    borderRadius: 'var(--radius-full)',
                    overflow: 'hidden',
                  }}
                >
                  <div
                    style={{
                      width: `${value}%`,
                      height: '100%',
                      background: getSkillColor(value),
                      borderRadius: 'var(--radius-full)',
                      transition: 'width 0.5s ease',
                    }}
                  />
                </div>
              </div>
            );
          })}
        </div>
      </div>

      {/* ===== МОДАЛКА ПРАКТИКИ ===== */}
      {isPracticing && selectedExercise && (
        <div
          role="dialog"
          aria-modal="true"
          aria-labelledby="practice-modal-title"
          style={{
            position: 'fixed',
            top: 0, left: 0, right: 0, bottom: 0,
            background: 'rgba(0, 0, 0, 0.88)',
            backdropFilter: 'blur(12px)',
            zIndex: 'var(--z-modal)',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            padding: '24px',
          }}
        >
          <div style={{
            background: 'var(--bg-panel)',
            maxWidth: '720px',
            width: '100%',
            maxHeight: '90vh',
            borderRadius: 'var(--radius-xl)',
            border: '1px solid var(--border-color)',
            padding: '32px',
            boxShadow: 'var(--shadow-lg)',
            overflowY: 'auto',
            position: 'relative',
          }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: '20px', gap: 12 }}>
              <div style={{ flex: 1, minWidth: 0 }}>
                <div
                  className="fl-section-label"
                  style={{ color: 'var(--accent)', display: 'flex', alignItems: 'center', gap: 8 }}
                >
                  <span
                    aria-hidden="true"
                    style={{
                      display: 'inline-block',
                      width: 6, height: 6, borderRadius: '50%',
                      background: 'var(--accent)',
                      boxShadow: '0 0 6px var(--accent)',
                      animation: 'fretlab-pulse 1.8s ease-in-out infinite',
                    }}
                  />
                  Сейчас практикуешь
                </div>
                <h2
                  id="practice-modal-title"
                  style={{ margin: '6px 0 4px 0', fontSize: 'var(--text-xl)', fontWeight: 900, color: 'var(--text-primary)' }}
                >
                  {selectedExercise.title}
                </h2>
                <div style={{ display: 'flex', gap: '6px', flexWrap: 'wrap' }}>
                  <span style={tagStyle('accent')}>{DIFFICULTY_LABELS[selectedExercise.difficulty]}</span>
                  <span style={tagStyle('muted')}>⏱️ {selectedExercise.estimatedTime}</span>
                  <span style={tagStyle('muted')}>
                    {CATEGORY_ICONS[selectedExercise.category]} {CATEGORY_LABELS[selectedExercise.category]}
                  </span>
                  {sessionStart !== null && (
                    <span
                      style={tagStyle('accent')}
                      aria-label={`Занимаешься ${formatSession(elapsed)}`}
                    >
                      ⌛ {formatSession(elapsed)}
                    </span>
                  )}
                </div>
              </div>
              <IconButton
                aria-label="Закрыть"
                title="Закрыть"
                size="md"
                onClick={handleCloseModal}
              >
                ✕
              </IconButton>
            </div>

            {renderExerciseContent(selectedExercise)}

            <div style={{ display: 'flex', gap: '12px', marginTop: '24px', borderTop: '1px solid var(--border-color)', paddingTop: '20px' }}>
              <Button
                variant="primary"
                size="lg"
                fullWidth
                onClick={handleCompleteExercise}
                iconLeft="✓"
              >
                Завершить урок
              </Button>
              <Button
                variant="secondary"
                size="lg"
                onClick={handleCloseModal}
              >
                Закрыть
              </Button>
            </div>
          </div>
        </div>
      )}

      {/* ===== МОДАЛКА АККОРДА ===== */}
      {showChordModal && selectedChord && (
        <ChordDictionaryModal
          chord={selectedChord}
          onClose={() => {
            setShowChordModal(false);
            setSelectedChord(null);
          }}
        />
      )}

      {/* ===== МОДАЛКА СБРОСА ПРОГРЕССА ===== */}
      {showResetConfirm && (
        <div
          role="alertdialog"
          aria-modal="true"
          aria-labelledby="reset-confirm-title"
          style={{
            position: 'fixed',
            inset: 0,
            background: 'rgba(0, 0, 0, 0.85)',
            backdropFilter: 'blur(8px)',
            zIndex: 'var(--z-modal)',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            padding: '24px',
          }}
        >
          <div style={{
            background: 'var(--bg-panel)',
            maxWidth: '420px',
            width: '100%',
            borderRadius: 'var(--radius-lg)',
            border: '1px solid var(--border-color)',
            padding: '24px',
            boxShadow: 'var(--shadow-lg)',
          }}>
            <div style={{ fontSize: 32, marginBottom: 8 }} aria-hidden="true">⚠️</div>
            <h2
              id="reset-confirm-title"
              style={{ margin: '0 0 8px 0', fontSize: 'var(--text-lg)', fontWeight: 800, color: 'var(--text-primary)' }}
            >
              Сбросить весь прогресс?
            </h2>
            <p style={{ margin: '0 0 20px 0', color: 'var(--text-muted)', fontSize: 'var(--text-sm)', lineHeight: 'var(--leading-relaxed)' }}>
              Это действие удалит {userProgress.completedExercises.length} выполненных уроков, серию из {userProgress.practiceStreak} дн. и все skill levels. Отменить нельзя.
            </p>
            <div style={{ display: 'flex', gap: 8 }}>
              <Button
                variant="danger"
                size="md"
                onClick={handleResetProgress}
                fullWidth
              >
                Да, сбросить
              </Button>
              <Button
                variant="secondary"
                size="md"
                onClick={() => setShowResetConfirm(false)}
                fullWidth
              >
                Отмена
              </Button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

function tagStyle(variant: 'accent' | 'muted'): React.CSSProperties {
  return {
    fontSize: 'var(--text-xs)',
    fontWeight: 700,
    color: variant === 'accent' ? 'var(--accent)' : 'var(--text-muted)',
    background: variant === 'accent' ? 'var(--color-accent-soft)' : 'var(--bg-secondary)',
    padding: '2px 10px',
    borderRadius: 'var(--radius-full)',
    fontFamily: 'var(--font-mono)',
    textTransform: 'uppercase',
    letterSpacing: '0.3px',
    whiteSpace: 'nowrap',
  };
}

export default PracticeDashboard;
